insert into public.categories (id, slug, icon, title, description, sort_order, is_visible) values
  ('image-tools', 'image-tools', 'Image', 'Image Tools', 'Compress, resize, crop, convert and inspect images directly in your browser. Your photos never leave your device.', 10, true),
  ('pdf-tools', 'pdf-tools', 'FileText', 'PDF Tools', 'Merge, split, rotate, reorder, number and watermark PDF documents locally, without uploading them anywhere.', 20, true),
  ('text-tools', 'text-tools', 'Type', 'Text Tools', 'Count words, change case, clean up lines, compare texts and generate slugs — fast utilities for writers and editors.', 30, true),
  ('developer-tools', 'developer-tools', 'Code', 'Developer Tools', 'Format JSON and XML, encode and decode data, inspect JWTs, convert timestamps and test regular expressions.', 40, true),
  ('calculators', 'calculators', 'Calculator', 'Calculators', 'Everyday calculators for percentages, discounts, VAT, ages, date ranges and aspect ratios.', 50, true),
  ('file-converters', 'file-converters', 'ArrowLeftRight', 'Converters', 'Convert CSV and JSON, units of measurement, temperatures, file sizes and color formats.', 60, true),
  ('productivity-tools', 'productivity-tools', 'Sparkles', 'Productivity Tools', 'Create QR codes, CSS gradients, placeholder text and live Markdown previews in seconds.', 70, true),
  ('security-generators', 'security-generators', 'ShieldCheck', 'Security & Generators', 'Generate strong passwords, UUIDs and SHA-256 hashes using your browser’s cryptographically secure APIs.', 80, true)
